import{z as A,x as s,o as B,c as p,q as i,j as o,D as e,d as t,s as n,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"BLP 需求估计的深入","description":"","frontmatter":{"title":"BLP 需求估计的深入","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/se-blp-deep.md","filePath":"econ/se-blp-deep.md","lastUpdated":1791063341000}'),d={name:"econ/se-blp-deep.md"};function m(h,E,D,b,c,C){const r=s("Mermaid");return B(),p("div",null,[E[2]||(E[2]=i('<h1 id="blp-需求估计的深入" tabindex="-1">BLP 需求估计的深入 <a class="header-anchor" href="#blp-需求估计的深入" aria-label="Permalink to &quot;BLP 需求估计的深入&quot;">​</a></h1><div class="epigraph"><p>随机系数给替代形状，份额给需求位置；但把弹性估对的是工具背后的经济学论证——工具错了，再聪明的数值与抽法都救不回反事实。</p><footer>—— 据 Berry, Levinsohn and Pakes, Econometrica 1995；Nevo, Econometrica 2001 整理</footer></div><p><a href="/econ/pe-case-map">上一课</a>把政策评估的案例收成一张图：设计是契约、推断对准目标、证据是组合物，估计量只是设计的兑现。本课是「结构估计深化」的第一课，单元「需求与供给」随后依次处理动态选择、生产技术与拍卖。从主干课的「能估出来」到「敢拿弹性做反事实」，还差四步：工具怎么构造与诊断、替代模式的识别靠什么变异、需求与供给矩如何联合、微观数据何时必须进来。本课写这四步，不重推 Berry 反演与收缩映射。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>缺口在矩条件 \\(\\mathbb{E}[Z&#39;\\xi]=0\\) 的两端。工具一端：\\(\\xi_{jt}\\) 与价格相关，特征工具若只是「自己与他者的特征」，弱与伪居其一——新车型的高 \\(\\xi\\) 常与广告、渠道投入同涨，而这些恰是可观测特征。矩一端：随机系数 \\(\\beta_i\\) 分布的维度靠矩钉住，市场里只有「两个产品、两个特征」时，份额变动填不满矩。更深一层：估出的弹性要送进<a href="/econ/merger-simulation">合并模拟</a>的一阶条件，供给边若完全没进估计，加成只能事后假设，方向可能错。</p><p><span class="marginnote">直觉类比：普通 logit 假设所有人用同一把尺子量价格；随机系数让每人的尺子刻度不同——有人对价格迟钝、有人极敏感。市场份额只是全体量完后的总票数，要从票数倒推出「尺子怎么分布」，靠的是市场之间、产品之间特征与价格的变异。</span></p><h3 id="工具的谱系与诊断" tabindex="-1">工具的谱系与诊断 <a class="header-anchor" href="#工具的谱系与诊断" aria-label="Permalink to &quot;工具的谱系与诊断&quot;">​</a></h3><p>工具分两族。需求侧：同一市场内其他产品的特征、其他市场的同产品特征——若 \\(\\xi\\) 是产品与市场效应，跨市场变异被排除出来。供给侧：成本移动元（投入价格、关税、运费）经均衡进价格而不进需求误差。构造后诊断：第一阶段强度按<a href="/econ/iv-weak-instruments">弱工具</a>课的规程查；再进一步用 \\(\\widehat{\\mathbb{E}}[\\xi\\mid X]\\) 的非线性投影逼近最优工具，并以 \\(J\\) 检验矩的内部一致。</p><p><span class="marginnote">Nevo 的麦片文把特征工具写实：用其他城市同一品牌的价格当工具，辩护是品牌质量全国同、成本冲击城市异。工具故事每篇重写，弱工具与 \\(J\\) 的诊断一样不能少。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>联合估计：需求矩 \\(\\mathbb{E}[Z^d\\xi]=0\\) 与供给矩同进目标函数。多产品 Bertrand 的一阶条件把 \\(p-mc\\) 与弹性连起来，有可观测成本数据时一并放进来，加成内生。随机系数的识别靠变异的「位置」：价格与特征在市场间的截面变异撬动 \\(\\beta_i\\) 分布的各阶矩，市场定义（城市、年份、渠道）因此是识别声明，不是数据清洗选择。</p><p>微观数据是第二把钳子：家庭面板的第二选择或「曾考虑清单」直接钉住 \\(\\beta_i\\) 分布的尾。代价是权重对齐：微观样本来自谁，宏观份额就来自谁，抽样层与市场层错位会把「谁被抽到」写成偏好。BLP 2004 的新车市场把调查微观数据与份额一起进似然，是这一步的原型。</p>',12)),(B(),o(l,null,{default:e(()=>[n(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHARE%5B%22%E4%BB%BD%E9%A2%9D%E5%8F%8D%E6%BC%94%20%CE%B4%22%5D%20--%3E%20MOM%5B%22%E9%9C%80%E6%B1%82%E7%9F%A9%E4%B8%8E%E4%BE%9B%E7%BB%99%E7%9F%A9%E5%90%8C%E7%9B%AE%E6%A0%87%22%5D%0A%20%20SUPPLY%5B%22%E6%88%90%E6%9C%AC%E7%A7%BB%E5%8A%A8%E5%85%83%E4%B8%8E%E4%B8%80%E9%98%B6%E6%9D%A1%E4%BB%B6%22%5D%20--%3E%20MOM%0A%20%20MICRO%5B%22%E5%BE%AE%E8%A7%82%E4%BA%8C%E6%AC%A1%E9%80%89%E6%8B%A9%22%5D%20--%3E%20RC%5B%22%E9%9A%8F%E6%9C%BA%E7%B3%BB%E6%95%B0%E5%88%86%E5%B8%83%E7%9A%84%E5%B0%BE%22%5D%0A%20%20RC%20--%3E%20MOM%0A%20%20MOM%20--%3E%20ELAS%5B%22%E5%BC%B9%E6%80%A7%E4%B8%8E%E5%86%85%E7%94%9F%E5%8A%A0%E6%88%90%22%5D%0A%20%20ELAS%20--%3E%20CF%5B%22%E5%90%88%E5%B9%B6%E4%B8%8E%E5%85%B3%E7%A8%8E%E5%8F%8D%E4%BA%8B%E5%AE%9E%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"机制是识别的变异从哪来。反演 \\(\\delta\\) 只用份额，关于 \\(\\beta_i\\) 分布的信息全部藏在份额如何随协变量变；特征工具的排除限制说的是对手特征经竞争进价格、不直接进本产品的 \\(\\xi\\)——这句辩护写不出机制，工具就只是回归惯例。供给矩是第二重钳制：弹性若有偏，观测价格在给定成本下不再被复现，拟合会暴露它。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"术语翻译：工具的「排除限制」就是「这个变量只能通过价格这一条管道影响份额，不能抄近道」。对手产品的特征满足它：它们抬高对手定价、间接抬高自己的价格，但不直接改变本产品在消费者心里的品质。若还能抄近道，工具就是伪的。")],-1)),E[6]||(E[6]=a("p",null,"替代模式同理。随机系数只在若干特征维度上转动，替代就只在那些维度上活络；合并模拟问「A 涨价流向谁」，答案由 \\(\\beta_i\\) 分布的形状决定。维度选少，交叉弹性矩阵退化，转移率错，\\(\\Delta p\\) 错——不是数值误差，是模型说错话。",-1)),(B(),o(l,null,{default:e(()=>[n(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20UP%5B%22%E5%93%81%E7%89%8C%20A%20%E6%B6%A8%E4%BB%B7%205%25%22%5D%20--%3E%20BETA%5B%22%E6%B6%88%E8%B4%B9%E8%80%85%E5%81%8F%E5%A5%BD%E7%B3%BB%E6%95%B0%20beta_i%20%E5%90%84%E4%B8%8D%E7%9B%B8%E5%90%8C%22%5D%0A%20%20BETA%20--%3E%20G1%5B%22%E4%BB%B7%E6%A0%BC%E6%95%8F%E6%84%9F%E7%9A%84%E4%B8%80%E7%BB%84%EF%BC%9A%E7%9B%B4%E6%8E%A5%E5%B0%91%E4%B9%B0%E6%88%96%E4%B9%B0%E4%BE%BF%E5%AE%9C%E8%B4%A7%22%5D%0A%20%20BETA%20--%3E%20G2%5B%22%E5%9C%A8%E4%B9%8E%E6%9F%90%E7%89%B9%E5%BE%81%E7%9A%84%E4%B8%80%E7%BB%84%EF%BC%9A%E8%BD%AC%E5%90%91%E8%AF%A5%E7%89%B9%E5%BE%81%E6%9C%80%E6%8E%A5%E8%BF%91%E7%9A%84%E5%AF%B9%E6%89%8B%22%5D%0A%20%20G1%20--%3E%20DEST%5B%22%E8%BD%AC%E7%A7%BB%E7%8E%87%E7%9F%A9%E9%98%B5%E5%86%B3%E5%AE%9A%E5%8F%8D%E4%BA%8B%E5%AE%9E%E6%B6%A8%E4%BB%B7%E5%B9%85%E5%BA%A6%22%5D%0A%20%20G2%20--%3E%20DEST%0A%20%20DEST%20--%3E%20ERR%5B%22beta%20%E5%88%86%E5%B8%83%E5%BD%A2%E7%8A%B6%E9%94%99%E4%BA%86%2C%20%E8%BD%AC%E7%A7%BB%E4%B8%8E%E4%BB%B7%E6%A0%BC%E5%85%A8%E9%94%99%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=i('<p><span class="marginnote">常见误区：初学者容易把「换个样本弹性就翻倍」当成数值误差去调算法。更可能的原因是市场定义换了——城市、年份或渠道的划法一变，撬动随机系数的变异就变。该做的是把两种划法都报出来当敏感性，而不是挑一个顺手的。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重推 Berry 1994 的闭式反演，不展开最优工具的渐近理论。嵌套 logit 可作廉价对照放进敏感性，但其组内 IIA 仍在。市场定义换一下弹性就翻倍时，报敏感性，不挑顺手的那个。动态耐用品需求（前向购买）留给下一课，本课的购买都是当期决策。</p><p>后课默认：弹性报数必带工具诊断与市场定义敏感性；供给矩能联合就联合；尾部有微观数据就别只靠间接矩。下一课动态离散选择把前向选择请进来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>工具两族：跨市场与对手特征进需求矩，成本移动元进供给矩，诊断沿用弱工具规程。</li><li>随机系数的识别藏在份额对协变量的变异里，市场定义是识别声明。</li><li>供给矩联合估计让加成内生，拟合有检验。</li><li>微观数据钉住分布的尾，权重须与份额来源对齐。</li><li>出处：Berry, Levinsohn and Pakes, <em>Econometrica</em> 1995；Berry, <em>RAND</em> 1994；Nevo, <em>Econometrica</em> 2001；Berry, Levinsohn and Pakes, <em>JPE</em> 2004。</li></ul>',6))])}const f=A(d,[["render",m]]);export{_ as __pageData,f as default};
